import Link from "next/link";

export type LegalBlock = string | { list: string[] } | { ordered: string[] };
export type LegalSection = { heading: string; blocks: LegalBlock[] };

const LEGAL_NAV = [
  { label: "Terms of Service", href: "/legal/terms" },
  { label: "Privacy Policy", href: "/legal/privacy" },
  { label: "Acceptable Use", href: "/legal/aup" },
  { label: "SLA", href: "/legal/sla" },
];

function Block({ block }: { block: LegalBlock }) {
  if (typeof block === "string") {
    return <p className="text-[15px] leading-relaxed text-slate-300">{block}</p>;
  }
  if ("list" in block) {
    return (
      <ul className="ml-1 space-y-2">
        {block.list.map((li, i) => (
          <li key={i} className="flex gap-3 text-[15px] leading-relaxed text-slate-300">
            <span className="mt-2.5 h-1.5 w-1.5 shrink-0 rounded-full bg-brand-400" />
            <span>{li}</span>
          </li>
        ))}
      </ul>
    );
  }
  return (
    <ol className="ml-1 space-y-2">
      {block.ordered.map((li, i) => (
        <li key={i} className="flex gap-3 text-[15px] leading-relaxed text-slate-300">
          <span className="shrink-0 font-semibold text-brand-300">{i + 1}.</span>
          <span>{li}</span>
        </li>
      ))}
    </ol>
  );
}

export function LegalDoc({
  title,
  updated,
  intro,
  sections,
  current,
}: {
  title: string;
  updated: string;
  intro: string;
  sections: LegalSection[];
  current: string;
}) {
  return (
    <div className="mx-auto max-w-5xl px-5 py-16 sm:px-6">
      <div className="grid gap-10 lg:grid-cols-[200px_1fr]">
        {/* Side nav */}
        <aside className="hidden lg:block">
          <div className="sticky top-24">
            <p className="section-label mb-3">Legal</p>
            <nav className="space-y-1">
              {LEGAL_NAV.map((l) => (
                <Link
                  key={l.href}
                  href={l.href}
                  className={`block rounded-lg px-3 py-2 text-sm transition-colors ${
                    l.href === current
                      ? "bg-white/[0.06] font-medium text-white"
                      : "text-slate-400 hover:bg-white/[0.03] hover:text-white"
                  }`}
                >
                  {l.label}
                </Link>
              ))}
            </nav>
          </div>
        </aside>

        {/* Body */}
        <article className="min-w-0">
          <p className="section-label mb-3">Legal</p>
          <h1 className="text-3xl font-bold tracking-tight sm:text-4xl">{title}</h1>
          <p className="mt-3 text-sm text-slate-500">Last updated: {updated}</p>

          <p className="mt-8 text-[15px] leading-relaxed text-slate-300">{intro}</p>

          <div className="mt-10 space-y-10">
            {sections.map((s, i) => (
              <section key={i} className="scroll-mt-24">
                <h2 className="text-lg font-semibold text-white">
                  <span className="mr-2 text-brand-400">{i + 1}.</span>
                  {s.heading}
                </h2>
                <div className="mt-3 space-y-3">
                  {s.blocks.map((b, bi) => (
                    <Block key={bi} block={b} />
                  ))}
                </div>
              </section>
            ))}
          </div>

          <div className="mt-12 border-t border-white/[0.06] pt-6 text-sm text-slate-500">
            Questions about this document?{" "}
            <Link href="/contact" className="text-brand-300 hover:underline">
              Contact us
            </Link>
            .
          </div>
        </article>
      </div>
    </div>
  );
}

