export type SectionId = string; // core | games | game-locations | locations | compare | blog | tools | servers | mods-N

/** Which section a plain marketing path belongs to. */
export function sectionForPath(path: string): SectionId {
  const p = path.replace(/\/+$/, "") || "/";
  if (p.startsWith("/blog")) return "blog";
  if (p.startsWith("/tools")) return "tools";
  if (p.startsWith("/servers")) return "servers";
  if (p.startsWith("/mods")) return "core";
  if (/^\/vps-vs-|-alternative$|^\/migrate-from-|^\/compare/.test(p)) return "compare";
  if (/^\/[^/]+-server-hosting\/[^/]+$/.test(p)) return "game-locations";
  if (GAME_LOCATION_SET.has(p.slice(1))) return "game-locations";
  if (LOCATION_SET.has(p.slice(1))) return "locations";
  if (/-server-hosting$|^\/plutonium-|^\/game-servers|^\/gaming-vps$|^\/free-minecraft$/.test(p)) return "games";
