  "/sign-up": `${CYRUS_HOST_TREE}/sign-up`,
  "/auth/nxeon/start": `${CYRUS_HOST_TREE}/auth/start`,
  "/auth/nxeon/callback": `${CYRUS_HOST_TREE}/auth/callback`,
  "/auth/handoff": `${CYRUS_HOST_TREE}/auth/handoff`,
  "/auth/logout": `${CYRUS_HOST_TREE}/auth/logout`,
  // The legal documents are served ON cyrus.my (same documents as nxeon.cloud/legal/*; one operator, one account), so
  // no page of cyrus.my sends the visitor to nxeon.cloud just to read the terms.
  "/legal/terms": `${CYRUS_HOST_TREE}/legal/terms`,
  "/legal/privacy": `${CYRUS_HOST_TREE}/legal/privacy`,
  "/legal/aup": `${CYRUS_HOST_TREE}/legal/aup`,
  "/legal/sla": `${CYRUS_HOST_TREE}/legal/sla`,
  "/legal": `${CYRUS_HOST_TREE}/legal/terms`,
};

/** APIs the Cyrus screens call (same handlers as on Nxeon). */
// "/api/log" is the error boundary's logger (components/ErrorState.tsx); without it crashes on cyrus.my were never logged.
const CYRUS_APIS = ["/api/cyrus", "/api/mod-builder", "/api/nxlabs/cyrus", "/api/log"];

export function cyrusHostRoute(a: { pathname: string; search: string; method: string; cfg: BridgeConfig }): HostRoute {
  const p = a.pathname;
  const read = a.method === "GET" || a.method === "HEAD";
  // The internal tree is the rewrite target of the public auth paths (Next may run middleware again on it): on the
  // Cyrus host it is just another name for them. Off the Cyrus host middleware 404s it, and its pages/handlers
  // refuse to render without the marker this middleware alone sets.
  if (under(p, CYRUS_HOST_TREE)) return { kind: "pass" };
  if (p.startsWith("/_next/") || p === "/favicon.ico" || p.startsWith("/.well-known/") || p.startsWith("/vendor/") || isStaticFilePath(p)) return { kind: "pass" };
  if (read && under(p, HELP_BASE_INTERNAL)) return { kind: "pass" };
  if (CYRUS_APIS.some((x) => under(p, x))) return { kind: "pass" };
  if (under(p, "/dashboard/cyrus")) return { kind: "pass" };
  if (under(p, "/studio")) return { kind: "rewrite", pathname: "/dashboard/cyrus" + p.slice("/studio".length) };
  if (!read && under(p, "/legal")) return { kind: "notfound" };
  if (CYRUS_PAGES[p]) return { kind: "rewrite", pathname: CYRUS_PAGES[p] };
  // Customer app (r39): /home, /new, /account, /assets, /servers, /wallet, /projects[/<id>] are the app tree (its pages 404 while CYRUS_CUSTOMER_APP is off).
  const app = appPath(p); if (app) return { kind: "rewrite", pathname: app };
  if (!read) return { kind: "notfound" };
  // Help center (r50): public /help[/<slug>] is the rewrite source for the (cyrus-help) route group; it 404s while CYRUS_CUSTOMER_APP is off.
  const help = helpPath(p); if (help) return { kind: "rewrite", pathname: help };
  if (p === "/") return { kind: "redirect", url: "/studio", status: 302 };
  if (p === "/login") return { kind: "redirect", url: "/sign-in" + a.search, status: 302 };
  if (p === "/register") return { kind: "redirect", url: "/sign-up" + a.search, status: 302 };
  // Portal pages (servers, wallet, billing...) live on Nxeon: hand the visitor over, same path.
  if (under(p, "/dashboard")) return { kind: "redirect", url: a.cfg.nxeonOrigin + p + a.search, status: 302 };
  // /legal/<doc> is a rewrite (CYRUS_PAGES above); an unknown /legal path falls through to 404.
  return { kind: "notfound" };
}

/** Public customer-app path -> internal path (null = not an app path). */
export function appPath(p: string): string | null {
  if (CYRUS_APP_PATHS[p]) return CYRUS_APP_PATHS[p];
  if (p.startsWith("/projects/") && /^\/projects\/[A-Za-z0-9_-]{1,64}$/.test(p)) return APP_BASE + p;
  return null;
}

/** Same-site post-sign-in destination on the Cyrus host: a single-slash path into the Cyrus surface, else /studio. */
export function safeCyrusNext(raw: string | null | undefined): string {
  const s = String(raw ?? "");
  if (!/^\/(?![/\\])[^\s]*$/.test(s) || s.length > 1536 || s.includes("\\")) return "/studio";
  const path = s.split(/[?#]/)[0];
  if (under(path, "/studio") || under(path, "/dashboard/cyrus") || path === "/auth/handoff" || appPath(path)) return s;
  return "/studio";

// Cyrus GDPR tooling (r40, SERVER ONLY): export everything Cyrus holds about one person, and plan / run an erasure of it.
// Cyrus' own tables only, through cyrusDb (the host seam). The platform account itself (User row, invoices, Nxeon data)
// is the host's: Nxeon's own GDPR process covers it, and this tool never touches it.
//
// Erasure is FAIL CLOSED: it runs only when CYRUS_GDPR_ERASE=1 on the server AND the caller passes the account's email
// typed back (the action checks it). Policy per table: lib/cyrus/admin/ops.ts CYRUS_GDPR_TABLES (delete / anonymise /
// retain-financial). It is idempotent: a second run finds nothing left to delete and anonymises nothing new.
import { randomBytes } from "node:crypto";
import { cyrusDb as db } from "../db";
import { ANON_USER, CYRUS_GDPR_TABLES, gdprPlan, type GdprTable } from "./ops";
import { contributorIdOf } from "../library/backend/studio-hook";
import { opaqueViewer } from "../library/backend/signed-url";

type Delegate = {
  count(a: unknown): Promise<number>;
  findMany(a: unknown): Promise<unknown[]>;
  deleteMany(a: unknown): Promise<{ count: number }>;
  updateMany(a: unknown): Promise<{ count: number }>;
};
const model = (name: string): Delegate | null => {
  const d = (db as unknown as Record<string, unknown>)[name];
  return d && typeof (d as Delegate).count === "function" ? (d as Delegate) : null;
};

/** The value that identifies the person in this table's column, or null when it cannot be derived (no library secret). */
export function subjectValue(t: Pick<GdprTable, "id">, userId: string, env: Record<string, string | undefined> = process.env): string | null {
  if (!t.id) return userId;
  const secret = env.CYRUS_LIBRARY_URL_SECRET;
  if (!secret) return null;
  return t.id === "contributor" ? contributorIdOf(secret, userId) : `u:${opaqueViewer(userId, secret).toLowerCase().replace(/[^a-z0-9_-]/g, "_")}`;
}

export const gdprEraseEnabled = (env: Record<string, string | undefined> = process.env) => env.CYRUS_GDPR_ERASE === "1";

export async function gdprCounts(userId: string): Promise<Record<string, number | null>> {
  const out: Record<string, number | null> = {};
  await Promise.all(CYRUS_GDPR_TABLES.map(async (t) => {
    const m = model(t.model);
    const v = subjectValue(t, userId);
    out[t.model] = m && v ? await m.count({ where: { [t.field]: v } }).catch(() => null) : null;
  }));
  return out;
}

export async function gdprPlanFor(userId: string) {
  return gdprPlan(await gdprCounts(userId));
}

const EXPORT_CAP = 5000; // rows per table; the export says when a table was cut

/** Every Cyrus row about the person, as JSON-safe data (secrets never stored in these tables). */
export async function gdprExport(userId: string, email: string | null): Promise<Record<string, unknown>> {
  const tables: Record<string, unknown> = {};
  const truncated: string[] = [];
  for (const t of CYRUS_GDPR_TABLES) {
    const m = model(t.model);
    const v = subjectValue(t, userId);
    if (!m || !v) continue;
    const rows = await m.findMany({ where: { [t.field]: v }, take: EXPORT_CAP + 1 }).catch(() => null);
    if (!rows) continue;
    if (rows.length > EXPORT_CAP) { truncated.push(t.model); rows.length = EXPORT_CAP; }
    tables[t.model] = rows;
  }
  const projects = (tables.cyrusProject as { id: string }[] | undefined)?.map((p) => p.id) ?? [];
  if (projects.length) {
    tables.cyrusRevision = await db.cyrusRevision.findMany({ where: { projectId: { in: projects } }, take: EXPORT_CAP }).catch(() => []);
    tables.cyrusProjectAsset = await db.cyrusProjectAsset.findMany({ where: { projectId: { in: projects } }, take: EXPORT_CAP }).catch(() => []);
  }
  return { schema: "cyrus-gdpr-export/1", subject: { id: userId, email }, exportedAt: new Date().toISOString(), note: "Cyrus data only. Your Nxeon account, invoices and servers are exported by Nxeon.", truncated, tables };
}

export type EraseResult = { deleted: Record<string, number>; anonymised: Record<string, number>; retained: Record<string, number>; anonId: string; salt: string };

export async function gdprErase(userId: string): Promise<EraseResult> {
  if (!gdprEraseEnabled()) throw new Error("erasure is off (CYRUS_GDPR_ERASE)");
  const salt = randomBytes(8).toString("hex");
  const anonId = ANON_USER(userId, salt);
  const res: EraseResult = { deleted: {}, anonymised: {}, retained: {}, anonId, salt };
  const projects = (await db.cyrusProject.findMany({ where: { userId }, select: { id: true } })).map((p) => p.id);
  if (projects.length) {
    res.deleted.cyrusRevision = (await db.cyrusRevision.deleteMany({ where: { projectId: { in: projects } } })).count;
    res.deleted.cyrusProjectAsset = (await db.cyrusProjectAsset.deleteMany({ where: { projectId: { in: projects } } })).count;
  }
  for (const t of CYRUS_GDPR_TABLES) {
    const m = model(t.model);
    const v = subjectValue(t, userId);
    if (!m || !v) continue;
    const where = { [t.field]: v };
    if (t.policy === "delete") res.deleted[t.model] = (await m.deleteMany({ where })).count;
    else if (t.policy === "anonymise") {
      const data: Record<string, unknown> = { [t.field]: anonId };
      if (t.model === "modBuild") Object.assign(data, { prompt: "(erased)", changeRequest: null, pluginName: null });
      if (t.model === "cyrusLibraryReport") data.note = null;
      res.anonymised[t.model] = (await m.updateMany({ where, data })).count;
    } else res.retained[t.model] = await m.count({ where });
  }
  return res;
}
