// "Login with Google" — Google OAuth 2.0 / OpenID Connect.
//
// Plain server-side module (NO "use server") — imported only by the two Google
// auth route handlers under app/api/auth/google. Never bundled to the client;
// no client secret or token is ever logged or returned to the browser.
//
// Nxeon is a server-side Next.js app, so we are a CONFIDENTIAL client: the
// Authorization Code flow with a client secret (client_secret_post). Google is
// the identity provider; we only ever ask for the user's identity, never any
// Google API scope beyond `openid email profile`.
//
// ---------------------------------------------------------------------------
// PROTOCOL CONSTANTS — Google's OIDC endpoints (stable, from
// https://accounts.google.com/.well-known/openid-configuration):
//   * authorize  https://accounts.google.com/o/oauth2/v2/auth
//   * token      https://oauth2.googleapis.com/token
//   * userinfo   https://openidconnect.googleapis.com/v1/userinfo
// ---------------------------------------------------------------------------

import { randomBytes } from "node:crypto";

export const GOOGLE_AUTHORIZE_URL = "https://accounts.google.com/o/oauth2/v2/auth";
export const GOOGLE_TOKEN_URL = "https://oauth2.googleapis.com/token";
export const GOOGLE_USERINFO_URL = "https://openidconnect.googleapis.com/v1/userinfo";

/** The scopes we request: identity only. */
export const GOOGLE_OAUTH_SCOPES = "openid email profile";

/** Random URL-safe string for the CSRF `state`. */
export function randomUrlSafe(bytes = 32): string {
  return randomBytes(bytes).toString("base64url");
}

/**
 * Redirect URI — must be registered verbatim on the Google OAuth client.
 * `${APP_URL}/api/auth/google/callback`.
 */
export function googleRedirectUri(): string {
  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
  return `${base}/api/auth/google/callback`;
}

/**
 * Is the OAuth client configured in this environment? When false the login page
 * HIDES the "Continue with Google" button, so nothing shows a broken flow before
 * the operator adds the credentials. Read at request time (not module top-level)
 * so an unset value never crashes boot.
 */
export function googleOauthConfigured(): boolean {
  return Boolean(
    (process.env.GOOGLE_CLIENT_ID ?? "").trim() &&
      (process.env.GOOGLE_CLIENT_SECRET ?? "").trim(),
  );
}

/** Build the Google consent URL for this sign-in attempt. */
export function googleAuthorizeUrl(opts: { state: string }): string {
  const url = new URL(GOOGLE_AUTHORIZE_URL);
  url.searchParams.set("client_id", (process.env.GOOGLE_CLIENT_ID ?? "").trim());
  url.searchParams.set("redirect_uri", googleRedirectUri());
