// Cyrus analytics + consent (r40): cookie consent for cyrus.my, privacy-safe attribution / referral capture, and the
// conversion-event spec for Meta and Google. PURE and client-safe (no imports, no network): the banner, the static
// landing script (public/cyrus/consent.js mirrors these rules) and the server all use these functions.
// Flags (all OFF): CYRUS_CONSENT (banner), CYRUS_ATTRIBUTION (store attribution), CYRUS_CONVERSIONS (send events).
// Rules:
//   - nothing optional is stored before a choice; "Reject all" is as easy as "Accept all"; the choice lasts 180 days
//   - referral code + UTM tags need ANALYTICS consent; ad click ids (fbclid, gclid) need MARKETING consent
//   - no third-party cookies: attribution crosses cyrus.my -> nxeon.cloud as a validated query parameter on the SSO
//     hand-off (r36), and is re-validated on arrival like any URL input
//   - conversion payloads carry no raw personal data: an email only as a SHA-256 the caller computed, nothing else

export const CYRUS_CONSENT_COOKIE = "cyrus_consent";
export const CYRUS_ATTR_COOKIE = "cyrus_attr";
export const CONSENT_MAX_AGE_S = 180 * 86_400;
export const ATTR_MAX_AGE_S = 30 * 86_400;
export const CONSENT_VERSION = 1;

export type Consent = { analytics: boolean; marketing: boolean; at: number; v: number };

export function serializeConsent(c: { analytics: boolean; marketing: boolean }, nowMs: number): string {
  return `v${CONSENT_VERSION}.a${c.analytics ? 1 : 0}.m${c.marketing ? 1 : 0}.${Math.floor(nowMs / 1000)}`;
}

/** null = no valid choice yet (show the banner). An older version also counts as no choice (ask again). */
export function parseConsent(raw: string | null | undefined): Consent | null {
  const m = /^v(\d+)\.a([01])\.m([01])\.(\d{9,11})$/.exec(raw ?? "");
  if (!m || Number(m[1]) !== CONSENT_VERSION) return null;
  return { v: Number(m[1]), analytics: m[2] === "1", marketing: m[3] === "1", at: Number(m[4]) * 1000 };
}

export type Attribution = { ref?: string; utm?: { source?: string; medium?: string; campaign?: string; content?: string; term?: string }; click?: { fbclid?: string; gclid?: string }; landing?: string; at?: number };

const REF = /^[A-Za-z0-9_-]{2,32}$/;
const UTM = /^[A-Za-z0-9 ._+:/-]{1,80}$/;
const CLICK = /^[A-Za-z0-9._-]{8,200}$/;
const PATH = /^\/[A-Za-z0-9/_-]{0,80}$/;

