// Cyrus token ledger: the ONLY code that moves tokens. Server only; plain module
// (safe in the worker). See docs/DOCUMENTATION.md "Cyrus token economy".
//
// Invariants:
//  - Every write runs in one transaction that first locks the account row (FOR UPDATE),
//    so all of one account's token operations are serialised.
//  - CyrusTokenLedger is append-only; `idemKey` is UNIQUE. An operation whose key already
//    exists is a no-op that reports `created: false` (webhook retries, re-runs, double clicks).
//  - Balance = SUM(lot.remaining) over unexpired lots. Due lots are expired (with a ledger
//    row) at the start of every operation, so a stale lot is never spent.
//  - Reserving moves nothing: it only raises `reserved`. Settling spends the ACTUAL cost
//    from lots (soonest-expiring first) and drops the hold. Nothing goes below zero; a cost
//    above what the account holds is recorded as a write-off (Nxeon absorbs it).
import { Prisma } from "@prisma/client";
import { cyrusDb as db } from "../db";
import { loadTokenConfig } from "./config";
import { planTokensFrozen } from "./rollover";

export type Tx = Prisma.TransactionClient;
const DAY = 86_400_000;

export type LedgerKind = "grant" | "purchase" | "reserve" | "spend" | "release" | "refund" | "expire" | "revoke";
export type LotSource = "server_initial" | "server_renewal" | "plan" | "topup" | "admin" | "refund";

class Duplicate extends Error {}

function isUniqueViolation(e: unknown): boolean {
  return (e as { code?: string })?.code === "P2002";
}

async function lock(tx: Tx, userId: string): Promise<{ createdAt: Date }> {
  await tx.$executeRaw`INSERT INTO "CyrusTokenAccount" ("userId", "updatedAt") VALUES (${userId}, now()) ON CONFLICT ("userId") DO NOTHING`;
  const rows = await tx.$queryRaw<{ createdAt: Date }[]>`SELECT "createdAt" FROM "CyrusTokenAccount" WHERE "userId" = ${userId} FOR UPDATE`;
  return rows[0];
}

async function sums(tx: Tx, userId: string): Promise<{ balance: number; reserved: number }> {
  const [b, r] = await Promise.all([
    tx.cyrusTokenLot.aggregate({ where: { userId, remaining: { gt: 0 } }, _sum: { remaining: true } }),
    tx.cyrusTokenReservation.aggregate({ where: { userId, status: "held" }, _sum: { amount: true } }),
