  /** Max tokens reserved+spent per rolling 24 h. */
  cyrus_tok_daily_spend_cap: "5000",
  cyrus_tok_new_account_days: "7",
  cyrus_tok_new_account_daily_cap: "1000",
  /** Below this the UI shows the low-balance state. */
export function tokensForCost(costUsd: number, model: CyrusModelId, cfg: TokenConfig): number {
  if (!(costUsd > 0)) return 0;
  return Math.max(cfg.minSpend, Math.ceil(costUsd * cfg.tokensPerUsd * (cfg.mult[model] ?? 1) - 1e-9));
}

export type SettleInput = { status: string; errorCode: string | null; costUsd: number; model: CyrusModelId; freeFailuresUsed: number };
export type SettleDecision = { charge: number; reason: "succeeded" | "refused" | "cancelled" | "failed_free" | "failed_partial" | "failed_over_limit" | "failed_infra" };

/** Cyrus capacity: failures that are capacity/AI-backend outages on OUR side (the AI was busy or rate-limited after the
 *  automatic retries, or no builder could take the build). Never charged and never counted against the free failures. */
export const INFRA_FAILURE_CODES: readonly string[] = ["ai_unavailable", "capacity"];

/** What a finished build costs. The charge is NOT capped at the reserve; the ledger caps it at the balance. */
export function settleCharge(i: SettleInput, cfg: TokenConfig): SettleDecision {
  const full = tokensForCost(i.costUsd, i.model, cfg);
  if (i.status === "succeeded") return { charge: full, reason: "succeeded" };
  if (i.errorCode === "refused") return { charge: cfg.chargeRefused ? full : 0, reason: "refused" };
  if (i.errorCode === "cancelled") return { charge: cfg.chargeCancelled ? full : 0, reason: "cancelled" };
  if (i.errorCode && INFRA_FAILURE_CODES.includes(i.errorCode)) return { charge: 0, reason: "failed_infra" };
  if (i.freeFailuresUsed >= cfg.freeFailures) return { charge: full, reason: "failed_over_limit" };
  const part = Math.ceil((full * cfg.failedChargePct) / 100);
  return part > 0 ? { charge: part, reason: "failed_partial" } : { charge: 0, reason: "failed_free" };
}

export function dailyCapFor(accountCreatedAt: Date, now: Date, cfg: TokenConfig): number {
  return now.getTime() - accountCreatedAt.getTime() < cfg.newAccountDays * DAY ? Math.min(cfg.newAccountDailyCap, cfg.dailyCap) : cfg.dailyCap;

