import type { LegalSection } from "@/components/marketing/LegalDoc";

/**
 * CYRUS LEGAL — the single source for the Cyrus Terms of Service and Cyrus Privacy Policy, rendered on
 * cyrus.my (/legal/terms, /legal/privacy) and on nxeon.cloud (/legal/cyrus-terms, /legal/cyrus-privacy).
 * Edit here only. Every statement must stay true to what the system does: when a practice changes, change the text
 * and bump CYRUS_LEGAL.version + updated.
 *
 * DRAFT (2026-10-15): written from the code and docs, not by a lawyer. Review before public launch. Open
 * questions for the owner are listed in agent-notes/cyrus-research/CT-legal-2026-10-15.md.
 *
 * Inline links inside a string use [label](href); the renderer turns them into anchors.
 * Links to the general Nxeon documents are ABSOLUTE (https://nxeon.cloud/...) because on cyrus.my /legal/terms and
 * /legal/privacy are THESE Cyrus documents, not Nxeon's.
 */
export const CYRUS_LEGAL = {
  /** Bumped whenever either document changes materially. Shown on both pages. */
  version: "1.0",
  effective: "October 15, 2026",
  updated: "October 15, 2026",
  /** ISO date for sitemap lastmod. */
  lastmod: "2026-10-15",
  canonicalOrigin: "https://cyrus.my",
} as const;

/** The two documents' paths on cyrus.my, for the host-aware sitemap (the SEO sitemap helper can import this). */
export const CYRUS_LEGAL_SITEMAP_PATHS = ["/legal/terms", "/legal/privacy"] as const;

const NX = "https://nxeon.cloud";
const NX_TERMS = `${NX}/legal/terms`;
const NX_PRIVACY = `${NX}/legal/privacy`;
const NX_AUP = `${NX}/legal/aup`;
const NX_SLA = `${NX}/legal/sla`;

export type CyrusDoc = {
  key: "terms" | "privacy";
  title: string;
  metaTitle: string;
  description: string;
  /** Path on cyrus.my (also the canonical path). */
  route: string;
  /** Path on nxeon.cloud. */
  nxRoute: string;
  intro: string;
  /** Short "what changed" hook shown under the date. */
  changed: string;
};

export const CYRUS_TERMS_DOC: CyrusDoc = {
  key: "terms",
  title: "Terms of Service — Cyrus",
  metaTitle: "Terms of Service — Cyrus",
  description: "The terms for using Cyrus, the AI-assisted Minecraft plugin and mod generator: accounts, tokens, acceptable use, your content, and liability.",
  route: "/legal/terms",
  nxRoute: "/legal/cyrus-terms",
  intro: "These terms apply when you use Cyrus. Cyrus is a product of Nxeon and runs on your Nxeon account, so Nxeon's own terms for billing, acceptable use and service levels also apply and are linked below.",
  changed: "First version of the Cyrus-specific terms. Before this, Cyrus used the general Nxeon Terms of Service.",
};

export const CYRUS_PRIVACY_DOC: CyrusDoc = {
  key: "privacy",
  title: "Privacy Policy — Cyrus",
  metaTitle: "Privacy Policy — Cyrus",
  description: "What personal data Cyrus handles, who processes it (including Google sign-in and the AI model provider), how long we keep it, and how to export or erase it.",
  route: "/legal/privacy",
  nxRoute: "/legal/cyrus-privacy",
  intro: "This policy explains what Cyrus does with your personal data. It covers the Cyrus website (cyrus.my) and the Cyrus studio. For the rest of your Nxeon account, the general Nxeon Privacy Policy also applies.",
  changed: "First version of the Cyrus-specific privacy policy, including the Google user data section.",
};

