import Link from "next/link";
import { CYRUS_LEGAL, cyrusPrivacySections, cyrusTermsSections, CYRUS_PRIVACY_DOC, CYRUS_TERMS_DOC, type CyrusDoc } from "@/lib/legal/cyrus";
import type { LegalBlock, LegalSection } from "@/components/marketing/LegalDoc";
import { supportEmail } from "@/lib/settings";
import type { Metadata } from "next";

/** Renders one Cyrus legal document (shared by cyrus.my /legal/{terms,privacy} and nxeon.cloud /legal/cyrus-{terms,privacy}). */

const LINK = /\[([^\]]+)\]\(([^)\s]+)\)/g;

/** `text [label](href) text` -> text + anchors. Only https:// and site-relative links are turned into anchors. */
export function linkify(s: string): React.ReactNode[] {
  const out: React.ReactNode[] = [];
  let last = 0;
  let m: RegExpExecArray | null;
  LINK.lastIndex = 0;
  while ((m = LINK.exec(s))) {
    if (m.index > last) out.push(s.slice(last, m.index));
    const href = m[2];
    const ok = /^https:\/\//.test(href) || /^\/(?!\/)/.test(href);
    out.push(ok ? <a key={m.index} href={href} className="underline decoration-white/30 underline-offset-2 hover:decoration-white">{m[1]}</a> : m[0]);
    last = m.index + m[0].length;
  }
  if (last < s.length) out.push(s.slice(last));
  return out;
}

function Block({ block }: { block: LegalBlock }) {
  if (typeof block === "string") return <p className="text-[15px] leading-relaxed text-slate-300">{linkify(block)}</p>;
  const items = "list" in block ? block.list : block.ordered;
  const Tag = "list" in block ? "ul" : "ol";
  return (
    <Tag className="ml-1 space-y-2">
      {items.map((li, i) => (
        <li key={i} className="flex gap-3 text-[15px] leading-relaxed text-slate-300">
          <span className="mt-2.5 h-1.5 w-1.5 shrink-0 rounded-full bg-white/40" aria-hidden="true" />
          <span>{linkify(li)}</span>
        </li>
      ))}
    </Tag>
  );
}

export async function cyrusLegalSections(doc: CyrusDoc): Promise<LegalSection[]> {
  const email = await supportEmail().catch(() => "support@nxeon.cloud");
  return doc.key === "terms" ? cyrusTermsSections(email) : cyrusPrivacySections(email);
}

export const cyrusDocFor = (key: "terms" | "privacy") => (key === "terms" ? CYRUS_TERMS_DOC : CYRUS_PRIVACY_DOC);

/** Metadata for both hosts: titled for Cyrus, indexable, canonical on cyrus.my. */
export function cyrusLegalMetadata(doc: CyrusDoc): Metadata {
  const url = `${CYRUS_LEGAL.canonicalOrigin}${doc.route}`;
  return {
    title: { absolute: doc.metaTitle },
    description: doc.description,
    alternates: { canonical: url },
    openGraph: { title: doc.metaTitle, description: doc.description, url, type: "article", siteName: "Cyrus" },
    robots: { index: true, follow: true },
  };
}

export async function CyrusLegalDoc({ doc, host }: { doc: CyrusDoc; host: "cyrus" | "nxeon" }) {
  const sections = await cyrusLegalSections(doc);
  const route = (d: CyrusDoc) => (host === "cyrus" ? d.route : d.nxRoute);
  const nav = [
    { label: "Terms of Service — Cyrus", href: route(CYRUS_TERMS_DOC), key: "terms" },
    { label: "Privacy Policy — Cyrus", href: route(CYRUS_PRIVACY_DOC), key: "privacy" },
  ];
  return (
    <div className="mx-auto max-w-5xl px-5 py-16 sm:px-6">
      <div className="grid gap-10 lg:grid-cols-[220px_1fr]">
        <aside className="hidden lg:block">
          <div className="sticky top-24">
            <p className="mb-3 text-xs font-semibold uppercase tracking-wider text-slate-500">Cyrus legal</p>
            <nav className="space-y-1" aria-label="Cyrus legal documents">
              {nav.map((l) => (
                <Link key={l.href} href={l.href} aria-current={l.key === doc.key ? "page" : undefined}
                  className={`block rounded-lg px-3 py-2 text-sm ${l.key === doc.key ? "bg-white/[0.06] font-medium text-white" : "text-slate-400 hover:text-white"}`}>
                  {l.label}
                </Link>
              ))}
            </nav>
            <p className="mb-2 mt-6 text-xs font-semibold uppercase tracking-wider text-slate-500">Nxeon</p>
            <nav className="space-y-1" aria-label="Nxeon legal documents">
              <a className="block px-3 py-1.5 text-sm text-slate-400 hover:text-white" href="https://nxeon.cloud/legal/terms">Nxeon Terms</a>
              <a className="block px-3 py-1.5 text-sm text-slate-400 hover:text-white" href="https://nxeon.cloud/legal/privacy">Nxeon Privacy</a>
              <a className="block px-3 py-1.5 text-sm text-slate-400 hover:text-white" href="https://nxeon.cloud/legal/aup">Acceptable Use</a>
              <a className="block px-3 py-1.5 text-sm text-slate-400 hover:text-white" href="https://nxeon.cloud/legal/sla">SLA</a>
            </nav>
          </div>
        </aside>
        <article className="min-w-0">
          <p className="mb-3 text-xs font-semibold uppercase tracking-wider text-slate-500">Cyrus legal</p>
          <h1 className="text-3xl font-bold tracking-tight sm:text-4xl">{doc.title}</h1>
          <p className="mt-3 text-sm text-slate-500">
            Version {CYRUS_LEGAL.version} · Effective {CYRUS_LEGAL.effective} · Last updated {CYRUS_LEGAL.updated}
          </p>
          <p className="mt-2 text-sm text-slate-400"><b className="font-medium text-slate-300">What changed:</b> {doc.changed}</p>
          <p className="mt-8 text-[15px] leading-relaxed text-slate-300">{doc.intro}</p>
          <div className="mt-10 space-y-10">
            {sections.map((s, i) => (
              <section key={i} className="scroll-mt-24">
                <h2 className="text-lg font-semibold text-white"><span className="mr-2 text-slate-500">{i + 1}.</span>{s.heading}</h2>
                <div className="mt-3 space-y-3">{s.blocks.map((b, bi) => <Block key={bi} block={b} />)}</div>
              </section>
            ))}
          </div>
        </article>
      </div>
    </div>
  );
}
EOF
