// Cyrus Terms of Service + Privacy Policy (CT, 2026-10-15). Static + pure: content, titles, links, host rewrite, Google OAuth wording.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { renderToStaticMarkup } from "react-dom/server";
import { CYRUS_LEGAL, CYRUS_LEGAL_SITEMAP_PATHS, CYRUS_PRIVACY_DOC, CYRUS_TERMS_DOC, cyrusPrivacySections, cyrusTermsSections } from "../lib/legal/cyrus";
import { linkify } from "../components/cyrus/legal/CyrusLegalDoc";
import { cyrusHostRoute } from "../lib/cyrus/bridge/routing";
import { bridgeConfig } from "../lib/cyrus/bridge/config";

const ROOT = path.resolve(__dirname, "..");
const read = (p: string) => fs.readFileSync(path.join(ROOT, p), "utf8");
const EMAIL = "support@nxeon.cloud";
const flat = (s: ReturnType<typeof cyrusTermsSections>) => s.flatMap((x) => [x.heading, ...x.blocks.flatMap((b) => (typeof b === "string" ? [b] : "list" in b ? b.list : b.ordered))]).join("\n");
const terms = flat(cyrusTermsSections(EMAIL));
const privacy = flat(cyrusPrivacySections(EMAIL));

describe("Cyrus legal documents", () => {
  it("are titled for Cyrus, not Nxeon", () => {
    assert.equal(CYRUS_TERMS_DOC.metaTitle, "Terms of Service — Cyrus");
    assert.equal(CYRUS_PRIVACY_DOC.metaTitle, "Privacy Policy — Cyrus");
    for (const d of [CYRUS_TERMS_DOC, CYRUS_PRIVACY_DOC]) {
      assert.doesNotMatch(d.title + d.metaTitle, /nxeon/i);
      assert.ok(d.description.length > 60 && d.description.length < 200);
    }
  });
  it("carry a version, an effective date and a what-changed hook", () => {
    assert.match(CYRUS_LEGAL.version, /^\d+\.\d+$/);
    assert.equal(CYRUS_LEGAL.effective, "October 15, 2026");
    assert.match(CYRUS_LEGAL.lastmod, /^\d{4}-\d\d-\d\d$/);
    assert.ok(CYRUS_TERMS_DOC.changed && CYRUS_PRIVACY_DOC.changed);
  });
  it("the Terms cover the required topics", () => {
    for (const re of [/Nxeon/, /AI-assisted/, /Minecraft is a trademark of Mojang/, /not affiliated with/, /private beta/, /username/i, /no cash value/, /Stripe/, /malware/i, /CC0/, /Anthropic/, /3\) months|three \(3\) months/, /governed by/, /indemnif/i, /support@nxeon\.cloud/]) {
      assert.match(terms, re, String(re));
    }
    assert.doesNotMatch(terms, /free refine(ment)?s? (are|is) (included|guaranteed)/i);
  });
  it("the Privacy Policy covers the required topics", () => {
    for (const re of [/Anthropic/, /Stripe/, /Cloudflare/, /Google/, /cookie/i, /180 days/, /Request export/, /Request deletion/, /14 day/, /under 18/, /public/i, /do not sell/i]) {
      assert.match(privacy, re, String(re));
    }
  });
  it("the Google user data section meets the OAuth consent screen requirements", () => {
    assert.match(privacy, /openid, email and profile/);
    assert.match(privacy, /Google API Services User Data Policy/);
    assert.match(privacy, /Limited Use/);
    assert.match(privacy, /do not sell Google user data/);
    assert.match(privacy, /do not use it for advertising/);
    assert.match(privacy, /revoke access/);
    assert.match(privacy, /Retention/);
    assert.match(privacy, /developers\.google\.com\/terms\/api-services-user-data-policy/);
  });
  it("links to general Nxeon documents are absolute (on cyrus.my /legal/terms is THIS document)", () => {
    for (const t of [terms, privacy]) {
      assert.match(t, /\]\(https:\/\/nxeon\.cloud\/legal\/(terms|privacy)\)/);
      assert.doesNotMatch(t, /\]\(\/legal\/(aup|sla)\)/);
    }
    assert.match(terms, /\]\(\/legal\/privacy\)/); // the Cyrus privacy policy, relative
    assert.match(privacy, /\]\(\/legal\/terms\)/);
  });
  it("no emoji, no placeholder markers, no hard-coded cash promises", () => {
    for (const t of [terms, privacy]) {
      assert.doesNotMatch(t, /\p{Extended_Pictographic}/u);
      assert.doesNotMatch(t, /TODO|TBD|lorem|\{\{/i);
    }
  });
  it("linkify turns [label](href) into anchors and refuses other schemes", () => {
    const html = renderToStaticMarkup(<>{linkify("see [Terms](https://nxeon.cloud/legal/terms) and [x](javascript:alert(1)) and [p](/legal/privacy)")}</>);
    assert.match(html, /<a [^>]*href="https:\/\/nxeon\.cloud\/legal\/terms"[^>]*>Terms<\/a>/);
    assert.match(html, /href="\/legal\/privacy"/);
    assert.doesNotMatch(html, /javascript:alert[^"]*"/);
  });
});

describe("Cyrus legal routing and pages", () => {
  const cfg = bridgeConfig({ CYRUS_DOMAIN_MODE: "1", NODE_ENV: "test" } as never);
  it("cyrus.my still rewrites /legal/* in place (GET only)", () => {
    for (const d of ["terms", "privacy", "aup", "sla"]) {
      assert.deepEqual(cyrusHostRoute({ pathname: `/legal/${d}`, search: "", method: "GET", cfg }), { kind: "rewrite", pathname: `/cyrus-host/legal/${d}` });
    }
    assert.equal(cyrusHostRoute({ pathname: "/legal/terms", search: "", method: "POST", cfg }).kind, "notfound");
  });
  it("cyrus-host terms and privacy pages render the Cyrus documents, indexable, canonical on cyrus.my", () => {
    for (const k of ["terms", "privacy"]) {
      const src = read(`app/cyrus-host/legal/${k}/page.tsx`);
      assert.match(src, /CyrusLegalDoc/);
      assert.doesNotMatch(src, /@\/app\/legal\//);
      assert.match(src, new RegExp(`CYRUS_${k.toUpperCase()}_DOC`));
      assert.match(read(`app/legal/cyrus-${k}/page.tsx`), /host="nxeon"/);
    }
    const comp = read("components/cyrus/legal/CyrusLegalDoc.tsx");
    assert.match(comp, /canonical: url/);
    assert.match(comp, /index: true/);
    assert.doesNotMatch(comp, /noindex|index: false/);
    assert.equal(CYRUS_LEGAL.canonicalOrigin, "https://cyrus.my");
  });
  it("exports the two sitemap paths for the host-aware sitemap", () => {
    assert.deepEqual([...CYRUS_LEGAL_SITEMAP_PATHS], ["/legal/terms", "/legal/privacy"]);
  });
});
EOF
